async function proxyTelegramLogin(req, path) {
  const name = path.slice("/_api/tg-auth/".length);
  if (!TELEGRAM_NAMES.has(name))
    return apiJSON({ json: { error: "Unknown Telegram auth action" } }, 404);
  if (!["GET", "POST"].includes(req.method))
    return apiJSON({ json: { error: "Method not allowed" } }, 405);
  if (req.method === "GET" && name !== "session" && name !== "status")
    return apiJSON({ json: { error: "Method not allowed" } }, 405);
  const host = "https://lizty666-stage.up.railway.app";
  if (req.method === "POST" && (req.headers.get("origin") !== host || !req.headers.get("content-type")?.startsWith("application/json")))
    return apiJSON({ json: { error: "Invalid origin" } }, 403);
  const headers = { Accept: "application/json", "Content-Type": "application/json", Origin: host };
  const cookie = req.headers.get("cookie");
  if (cookie && cookie.length < 4096)
    headers["Cookie"] = cookie;
  let body;
  if (req.method === "POST") {
    body = await req.text();
    if (body.length > 8192)
      return apiJSON({ json: { error: "Request too large" } }, 413);
  }
  try {
    const r = await fetch("https://lizty666-api-stage.up.railway.app/v1/tg-auth/" + name, { method: req.method, headers, body, redirect: "manual", signal: AbortSignal.timeout(16000) });
    const payload = await r.text();
    if (payload.length > 15000)
      return apiJSON({ json: { error: "Invalid login reply" } }, 502);
    const h = { ...HEADERS, "Cache-Control": "no-store", "Content-Type": "application/json; charset=utf-8" };
    const c = r.headers.get("set-cookie");
    if (c && c.length < 1200)
      h["Set-Cookie"] = c;
    return new Response(payload, { status: r.status, headers: h });
  } catch {
    return apiJSON({ json: { error: "Telegram sign-in temporarily unavailable" } }, 503);
  }
}
